WITH valid_departments AS (SELECT * FROM departments WHERE location = 'Tokyo'), summary AS (SELECT CASE WHEN budget >= 4301000 THEN 'high' WHEN budget >= 1912000 THEN 'mid' ELSE 'low' END AS budget_bucket, COUNT(*) AS total_count, AVG(budget) AS avg_budget FROM valid_departments GROUP BY CASE WHEN budget >= 4301000 THEN 'high' WHEN budget >= 1912000 THEN 'mid' ELSE 'low' END) SELECT budget_bucket, total_count FROM summary WHERE total_count < 5
